import itertools

def is_kawaii(seq):
    # seq is a tuple of positive integers
    # for each k >= 2, if k is in seq, then k-1 is in seq, 
    # and first occurrence of k-1 comes before the last occurrence of k
    distinct_elements = set(seq)
    for k in distinct_elements:
        if k >= 2:
            if (k - 1) not in distinct_elements:
                return False
            # Find first occurrence of k-1
            first_k_minus_1 = seq.index(k - 1)
            # Find last occurrence of k
            last_k = -1
            for i in range(len(seq) - 1, -1, -1):
                if seq[i] == k:
                    last_k = i
                    break
            if first_k_minus_1 >= last_k:
                return False
    return True

def count_kawaii(n):
    count = 0
    # The maximum possible value in a kawaii sequence of length n is n.
    # because if k is in it, then 1, 2, ..., k-1 must also be in it.
    # So k <= n.
    for seq in itertools.product(range(1, n + 1), repeat=n):
        if is_kawaii(seq):
            count += 1
    return count

for n in range(1, 7):
    print(f"n={n}, count={count_kawaii(n)}")

